(() => {
  const toMinutes = (hhmm) => {
    const parts = String(hhmm).split(":");
    return Number(parts[0]) * 60 + Number(parts[1]);
  };
  const checkFields = (w) => {
    for (const key of Object.keys(w)) {
      if (key !== "start" && key !== "end") {
        throw new Error("unknown field: " + key);
      }
    }
  };
  function windowOverlap(first, second) {
    checkFields(first);
    checkFields(second);
    const s1 = toMinutes(first.start);
    const e1 = toMinutes(first.end);
    const s2 = toMinutes(second.start);
    const e2 = toMinutes(second.end);
    const minutes = Math.max(0, Math.min(e1, e2) - Math.max(s1, s2));
    return { overlaps: minutes > 0, minutes };
  }
  return { windowOverlap };
})()

