build.unitScript:
test("overlapping windows 09:00-11:00 and 10:30-12:00 overlap by 30 minutes", () => {
  const r = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00" });
  assert.deepEqual(r, { overlaps: true, minutes: 30 });
});
test("windows that only touch at 12:00 do not overlap and give 0 minutes", () => {
  const r = code.windowOverlap({ start: "09:00", end: "12:00" }, { start: "12:00", end: "13:00" });
  assert.deepEqual(r, { overlaps: false, minutes: 0 });
});
test("swapping the order of the two windows gives the same 30 minute overlap", () => {
  const r = code.windowOverlap({ start: "10:30", end: "12:00" }, { start: "09:00", end: "11:00" });
  assert.deepEqual(r, { overlaps: true, minutes: 30 });
});
test("windows with a gap between them do not overlap and give 0 minutes", () => {
  const r = code.windowOverlap({ start: "08:00", end: "09:00" }, { start: "10:00", end: "11:00" });
  assert.deepEqual(r, { overlaps: false, minutes: 0 });
});
test("a window fully inside another overlaps by the inner window length", () => {
  const r = code.windowOverlap({ start: "09:00", end: "13:00" }, { start: "10:00", end: "11:00" });
  assert.deepEqual(r, { overlaps: true, minutes: 60 });
});
test("an extra field on either window throws unknown field with its name", () => {
  assert.throws(() => code.windowOverlap({ start: "09:00", end: "11:00", driver: "A" }, { start: "10:30", end: "12:00" }), /unknown field: driver/);
  assert.throws(() => code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00", day: "Mon" }), /unknown field: day/);
});

build.testScript:
test("overlap minutes are 30 when 09:00 to 11:00 meets 10:30 to 12:00", function() {
  var result = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00" });
  assert.equal(result.minutes, 30);
});
test("windows are overlapping when 09:00 to 11:00 meets 10:30 to 12:00", function() {
  var result = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00" });
  assert.equal(result.overlaps, true);
});
test("windows that only touch at an end do not overlap and the overlap is 0 minutes", function() {
  var result = code.windowOverlap({ start: "09:00", end: "12:00" }, { start: "12:00", end: "13:00" });
  assert.equal(result.overlaps, false);
  assert.equal(result.minutes, 0);
});
test("swapped overlapping windows still overlap by 30 minutes", function() {
  var result = code.windowOverlap({ start: "10:30", end: "12:00" }, { start: "09:00", end: "11:00" });
  assert.equal(result.overlaps, true);
  assert.equal(result.minutes, 30);
});
test("swapped windows that only touch still do not overlap and the overlap is 0 minutes", function() {
  var result = code.windowOverlap({ start: "12:00", end: "13:00" }, { start: "09:00", end: "12:00" });
  assert.equal(result.overlaps, false);
  assert.equal(result.minutes, 0);
});
test("overlap minutes are 0 when 09:00 to 11:00 is entirely before 12:00 to 13:00", function() {
  var result = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "12:00", end: "13:00" });
  assert.equal(result.minutes, 0);
});

